public List<List<Integer>> permute(int[] nums){
    List<List<Integer>> res = new ArrayList<>();
    if(nums==null) return res;
    int n = nums.length;
    if(n==0){ res.add(new ArrayList<>()); return res;}
    int[] arr = nums.clone();
    // sort to start with first lexicographic
    java.util.Arrays.sort(arr);
    java.util.List<Integer> list = new ArrayList<>(n);
