    java.util.ArrayList<Integer> tmp = new ArrayList<>(n);
    for(int val : arr){ tmp.add(val); }
    res.add(tmp);
    while (true) {
        // find pivot
        int i = n-2;
        while(i>=0 && arr[i] > arr[i+1]) i--;
        if(i<0) break;
        int j = n-1;
        while(arr[j] < arr[i]) j--;
        // swap arr[i], arr[j]
        int tmpv = arr[i]; arr[i] = arr[j]; arr[j] = tmpv;
        // reverse suffix from i+1 to end
        int left=i+1, right=n-1;
        while(left<right){
            int t=arr[left]; arr[left]=arr[right]; arr[right]=t;
            left++; right--;
        }
        // copy arr to list
        java.util.ArrayList<Integer> newList = new java.util.ArrayList<>(n);
        for(int val: arr) newList.add(val);
        res.add(newList);
    }
    return res;
}

