public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    int result = num;
    while (result >= 10) {
        int sum = 0;
        int temp = result;
        while (temp > 0) {
            sum += temp % 10;
            temp /= 10;
        }
        result = sum;
    }
    return result;
}

